import{_ as t,o as a,c as i,a as l}from"./app.DLPSkIGI.js";const u=JSON.parse('{"title":"Polyglot Governance Parity Audit","description":"","frontmatter":{},"headers":[],"relativePath":"governance/POLYGLOT_GOVERNANCE_PARITY_AUDIT_2026-02-20.md","filePath":"governance/POLYGLOT_GOVERNANCE_PARITY_AUDIT_2026-02-20.md","lastUpdated":1771753292000}'),o={name:"governance/POLYGLOT_GOVERNANCE_PARITY_AUDIT_2026-02-20.md"};function r(n,e,d,s,c,h){return a(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="polyglot-governance-parity-audit" tabindex="-1">Polyglot Governance Parity Audit <a class="header-anchor" href="#polyglot-governance-parity-audit" aria-label="Permalink to &quot;Polyglot Governance Parity Audit&quot;">​</a></h1><p>undefined<strong>Date:</strong> 2026-02-20 undefined<strong>Repo:</strong> <code>thegent</code> undefined<strong>Status:</strong> Audit complete, rollout plan defined</p><hr><h2 id="_1-scope" tabindex="-1">1. Scope <a class="header-anchor" href="#_1-scope" aria-label="Permalink to &quot;1. Scope&quot;">​</a></h2><p>This audit covers:</p><ul><li>Language families: Go, TS/JS (+ variations), Python (+ variations), Java, C/C++, C#/.NET, Rust, Zig, Mojo, and additional supported stacks.</li><li>Non-language file types: shell, JSON/YAML/TOML, Markdown, infra/config artifacts.</li><li>Non-file/program governance: traceability, contracts, attestation, reliability/SLO, debt/playbook contracts, and on-chain/formal governance hooks.</li></ul><p>Parity target means each stack has:</p><ol><li>Lint + format + test baseline.</li><li>Security/dependency checks where applicable.</li><li>Pre-commit + CI + task-runner integration.</li><li>Shared governance overlays (file length, suppression policy, traceability/reporting).</li></ol><hr><h2 id="_2-evidence-anchors" tabindex="-1">2. Evidence Anchors <a class="header-anchor" href="#_2-evidence-anchors" aria-label="Permalink to &quot;2. Evidence Anchors&quot;">​</a></h2><ul><li>Templates inventory: <code>templates/quality/</code> (multi-stack policies and tool configs).</li><li>Runtime hooks and gate engine: <code>hooks/governance-gates.sh</code>, <code>hooks/hook-config.yaml</code>, <code>hooks/async-test-runner.sh</code>.</li><li>Current execution wiring: <ul><li><code>Taskfile.yml</code> (quality tasks),</li><li><code>.pre-commit-config.yaml</code> (local gates),</li><li><code>.github/workflows/ci.yml</code> (CI),</li><li><code>.github/workflows/release.yml</code> (SBOM/provenance).</li></ul></li><li>Shared max-lines gate implementation: <ul><li><code>scripts/max-lines-gate.sh</code>,</li><li><code>crates/thegent-utils/src/bin/max_lines.rs</code>.</li></ul></li><li>Speed contract: <ul><li><code>docs/governance/POLYGLOT_GOVERNANCE_SPEED_SPEC_2026-02-20.md</code>.</li></ul></li></ul><hr><h2 id="_3-current-parity-matrix-code-file-types" tabindex="-1">3. Current Parity Matrix (Code + File Types) <a class="header-anchor" href="#_3-current-parity-matrix-code-file-types" aria-label="Permalink to &quot;3. Current Parity Matrix (Code + File Types)&quot;">​</a></h2><p>Legend:</p><ul><li><code>A</code> = active and wired in current repo execution path.</li><li><code>P</code> = partially wired (some pieces exist, not full parity).</li><li><code>T</code> = template-ready only (governance intent exists, not wired).</li><li><code>M</code> = missing.</li></ul><table tabindex="0"><thead><tr><th>Surface</th><th style="text-align:right;">Templates</th><th style="text-align:right;">Task/Hook/CI Wiring</th><th>Status</th><th>Notes</th></tr></thead><tbody><tr><td>Python (py, pyi)</td><td style="text-align:right;">Yes</td><td style="text-align:right;">Strong</td><td><code>A</code></td><td>Ruff/ty/basedpyright/mypy/pytest/security present in task + CI.</td></tr><tr><td>Go</td><td style="text-align:right;">Yes</td><td style="text-align:right;">Partial</td><td><code>P</code></td><td>Go exists in max-lines + hook extension lists; no dedicated Go lane in main <code>thegent</code> CI.</td></tr><tr><td>TS/JS (ts,tsx,js,jsx,mjs,cjs)</td><td style="text-align:right;">Yes</td><td style="text-align:right;">Partial</td><td><code>P</code></td><td>Oxlint template parity logic exists in governance gate; not fully wired as first-class CI lane in <code>thegent</code>.</td></tr><tr><td>Shell (sh,zsh,bash,bats)</td><td style="text-align:right;">Yes</td><td style="text-align:right;">Partial</td><td><code>P</code></td><td>ShellCheck in Taskfile and template; not enforced in CI workflow currently.</td></tr><tr><td>JSON/YAML/TOML</td><td style="text-align:right;">Yes</td><td style="text-align:right;">Partial</td><td><code>P</code></td><td>pre-commit checks exist; stronger schema policy exists mostly in governance hooks.</td></tr><tr><td>Markdown/docs</td><td style="text-align:right;">Yes (markdownlint/vale templates)</td><td style="text-align:right;">Weak</td><td><code>P</code></td><td>Docs build gate exists; markdown lint policy not fully wired in CI/pre-commit.</td></tr><tr><td>Rust</td><td style="text-align:right;">Yes</td><td style="text-align:right;">Partial</td><td><code>P</code></td><td>Rust assets and benchmarks exist; no first-class fmt/clippy/test/audit lane in main CI yet.</td></tr><tr><td>Zig</td><td style="text-align:right;">No dedicated template file</td><td style="text-align:right;">Partial</td><td><code>P</code></td><td>Tooling setup + build and max-lines support exist; no fmt/test policy lane wired.</td></tr><tr><td>Mojo</td><td style="text-align:right;">No dedicated template file</td><td style="text-align:right;">Minimal</td><td><code>P</code></td><td>Mentioned in setup and max-lines extension list; no formatter/test/security lanes wired.</td></tr><tr><td>Java</td><td style="text-align:right;">Yes (checkstyle)</td><td style="text-align:right;">Template only</td><td><code>T</code></td><td>No active Java lint/test lane wired.</td></tr><tr><td>C/C++</td><td style="text-align:right;">Yes (clang-tidy/cppcheck)</td><td style="text-align:right;">Template only</td><td><code>T</code></td><td>No active C/C++ lane wired.</td></tr><tr><td>C#/.NET</td><td style="text-align:right;">No dedicated quality template currently</td><td style="text-align:right;">Missing</td><td><code>M</code></td><td>No active .NET lane or template in current quality set.</td></tr><tr><td>Kotlin/Swift/Dart/PHP/Ruby/Perl/Lua/Terraform/etc</td><td style="text-align:right;">Yes (various templates)</td><td style="text-align:right;">Template only</td><td><code>T</code></td><td>Policy scaffolding exists but not executed as lanes.</td></tr></tbody></table><hr><h2 id="_4-shared-cross-language-governance-status" tabindex="-1">4. Shared Cross-Language Governance Status <a class="header-anchor" href="#_4-shared-cross-language-governance-status" aria-label="Permalink to &quot;4. Shared Cross-Language Governance Status&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Cross-language Gate</th><th>Status</th><th>Notes</th></tr></thead><tbody><tr><td>Max file length gate</td><td><code>P</code></td><td>Implemented (Rust + Zig runner + shell wrapper) but not yet fully wired into pre-commit + CI + task defaults.</td></tr><tr><td>Suppression policy blocker</td><td><code>A</code> (template), <code>P</code> (runtime)</td><td>Template pre-commit rule exists; repo-level full enforcement still needs unified rollout.</td></tr><tr><td>Smart changed-file execution</td><td><code>A</code></td><td>Hook config supports changed/all scopes and incremental analysis.</td></tr><tr><td>Async test dispatch by file extension</td><td><code>A</code></td><td>Broad extension routing exists across many languages.</td></tr><tr><td>Trace parity template audit</td><td><code>A</code> (for py/go/oxlint)</td><td>Existing trace parity gate currently focuses on ruff/golangci/oxlint semantics.</td></tr><tr><td>Per-stack policy spec centralization</td><td><code>P</code></td><td>Strong template inventory exists; stack execution contracts are uneven.</td></tr></tbody></table><hr><h2 id="_5-non-file-program-governance-contracts-traceability-smart-governance" tabindex="-1">5. Non-File / Program Governance (Contracts, Traceability, Smart Governance) <a class="header-anchor" href="#_5-non-file-program-governance-contracts-traceability-smart-governance" aria-label="Permalink to &quot;5. Non-File / Program Governance (Contracts, Traceability, Smart Governance)&quot;">​</a></h2><p>Current governance engine already supports extensive non-code controls:</p><ul><li>PRD/ledger/DAG compile and lifecycle gates.</li><li>Agent claim schema + evidence lifecycle validation.</li><li>Reliability SLO and flake quarantine governance.</li><li>Brownfield/greenfield/probabilistic delivery-model gates.</li><li>Rolling-wave and assurance-case schema gates.</li><li>Privacy proof, on-chain adapter/transition gates.</li><li>Formal methods and formal registry gates.</li><li>Debt registry and playbook contract gates.</li><li>Artifact quality and SCC metrics gate.</li></ul><h3 id="important-gaps-in-this-layer" tabindex="-1">Important gaps in this layer <a class="header-anchor" href="#important-gaps-in-this-layer" aria-label="Permalink to &quot;Important gaps in this layer&quot;">​</a></h3><ol><li><code>onchain-contract</code> gate currently reports stub mode when contracts exist but toolchain gates are not installed/evaluated.</li><li><code>formal-methods</code> gate currently reports stub mode when formal specs exist but TLC/Dafny/Alloy evaluators are not installed/wired.</li><li>Schema coverage is uneven between contract artifacts and repository-level schema directories; some gates rely on runtime/project-local schemas.</li></ol><p>Net: governance architecture is strong, but some advanced assurance gates are still stubs or environment-dependent.</p><hr><h2 id="_6-gap-summary-by-priority" tabindex="-1">6. Gap Summary by Priority <a class="header-anchor" href="#_6-gap-summary-by-priority" aria-label="Permalink to &quot;6. Gap Summary by Priority&quot;">​</a></h2><h3 id="priority-0-already-strong" tabindex="-1">Priority 0 (already strong) <a class="header-anchor" href="#priority-0-already-strong" aria-label="Permalink to &quot;Priority 0 (already strong)&quot;">​</a></h3><ul><li>Python baseline quality lane.</li><li>Governance gate framework for non-code artifacts and policy enforcement.</li><li>Release SBOM/provenance path.</li></ul><h3 id="priority-1-close-to-parity-finish-wiring" tabindex="-1">Priority 1 (close to parity, finish wiring) <a class="header-anchor" href="#priority-1-close-to-parity-finish-wiring" aria-label="Permalink to &quot;Priority 1 (close to parity, finish wiring)&quot;">​</a></h3><ul><li>Rust lane: fmt + clippy + tests + security dependency checks.</li><li>TS/JS lane: strict lint/format/test lane in CI aligned with policy templates.</li><li>Go lane: first-class CI/task parity in this repo.</li><li>Shared max-lines gate: enforce in pre-commit/CI/task.</li></ul><h3 id="priority-2-template-rich-execution-poor" tabindex="-1">Priority 2 (template-rich, execution-poor) <a class="header-anchor" href="#priority-2-template-rich-execution-poor" aria-label="Permalink to &quot;Priority 2 (template-rich, execution-poor)&quot;">​</a></h3><ul><li>Java and C/C++ lanes from existing templates.</li><li>Shell/docs/config lint gates as consistent mandatory checks.</li></ul><h3 id="priority-3-missing-foundation" tabindex="-1">Priority 3 (missing foundation) <a class="header-anchor" href="#priority-3-missing-foundation" aria-label="Permalink to &quot;Priority 3 (missing foundation)&quot;">​</a></h3><ul><li>C#/.NET lane definition (toolchain, templates, CI hooks).</li><li>Mojo and Zig dedicated formatter/test lane definitions.</li></ul><hr><h2 id="_7-formal-rollout-plan-phased" tabindex="-1">7. Formal Rollout Plan (Phased) <a class="header-anchor" href="#_7-formal-rollout-plan-phased" aria-label="Permalink to &quot;7. Formal Rollout Plan (Phased)&quot;">​</a></h2><h3 id="phase-a-core-parity-substrate-all-stacks" tabindex="-1">Phase A: Core parity substrate (all stacks) <a class="header-anchor" href="#phase-a-core-parity-substrate-all-stacks" aria-label="Permalink to &quot;Phase A: Core parity substrate (all stacks)&quot;">​</a></h3><ol><li>Wire shared max-lines gate in pre-commit + CI + <code>task lint</code>.</li><li>Define normalized output schema for all check runners.</li><li>Add policy severity tiers (<code>advisory</code>, <code>soft_fail</code>, <code>hard_fail</code>) with explicit owner/date.</li></ol><h3 id="phase-b-primary-stack-parity-go-ts-python-rust-shell" tabindex="-1">Phase B: Primary stack parity (Go/TS/Python/Rust/Shell) <a class="header-anchor" href="#phase-b-primary-stack-parity-go-ts-python-rust-shell" aria-label="Permalink to &quot;Phase B: Primary stack parity (Go/TS/Python/Rust/Shell)&quot;">​</a></h3><ol><li>Rust: <code>fmt</code>, <code>clippy</code>, <code>test</code>, dependency/security checks.</li><li>Go: format/lint/test/security parity in this repo’s CI and tasks.</li><li>TS/JS: strict lint/format/type/test lane aligned with oxlint template + boundaries policy.</li><li>Shell/docs/config: shellcheck + markdown/config linting lanes.</li></ol><h3 id="phase-c-secondary-stack-activation-java-c-c-zig-mojo-net" tabindex="-1">Phase C: Secondary stack activation (Java/C/C++/Zig/Mojo/.NET) <a class="header-anchor" href="#phase-c-secondary-stack-activation-java-c-c-zig-mojo-net" aria-label="Permalink to &quot;Phase C: Secondary stack activation (Java/C/C++/Zig/Mojo/.NET)&quot;">​</a></h3><ol><li>Activate Java lane from checkstyle template + test lane.</li><li>Activate C/C++ lane from clang-tidy/cppcheck templates + build/test lane.</li><li>Add Zig lane (<code>fmt</code>/build/test) and Mojo lane (<code>format</code>/compile/test) policies.</li><li>Add C#/.NET baseline lane (format/lint/build/test/security) and add template set.</li></ol><h3 id="phase-d-advanced-governance-completion" tabindex="-1">Phase D: Advanced governance completion <a class="header-anchor" href="#phase-d-advanced-governance-completion" aria-label="Permalink to &quot;Phase D: Advanced governance completion&quot;">​</a></h3><ol><li>Replace stub on-chain/formal gates with real toolchain-backed evaluators where applicable.</li><li>Add schema hard-fail checks for all contract outputs.</li><li>Add governance SLO dashboards (gate latency, flake, failure trend, waiver debt).</li></ol><hr><h2 id="_8-execution-rules-required" tabindex="-1">8. Execution Rules (Required) <a class="header-anchor" href="#_8-execution-rules-required" aria-label="Permalink to &quot;8. Execution Rules (Required)&quot;">​</a></h2><ol><li>Native tool semantics stay native; thegent orchestrates and governs.</li><li>Adapter/wrapper first, rewriter last.</li><li>Every exception/waiver requires owner, reason, expiry, and cleanup issue.</li><li>New lanes start advisory and graduate to hard-fail only after baseline stabilization.</li><li>All lanes must support changed-files mode locally and full-scan mode in CI/nightly.</li></ol><hr><h2 id="_9-immediate-next-batch" tabindex="-1">9. Immediate Next Batch <a class="header-anchor" href="#_9-immediate-next-batch" aria-label="Permalink to &quot;9. Immediate Next Batch&quot;">​</a></h2><ol><li>Integrate max-lines gate into: <ul><li><code>.pre-commit-config.yaml</code>,</li><li><code>Taskfile.yml</code> (<code>lint</code> path),</li><li><code>.github/workflows/ci.yml</code> (<code>quality</code> job).</li></ul></li><li>Add Rust quality job in CI (fmt + clippy + tests + audit/deny).</li><li>Add shell/docs/config job in CI (shellcheck + markdown/config lint).</li><li>Draft lane spec for Java/C/C++/Zig/Mojo/.NET in a single policy contract file for staged activation.</li></ol><hr><h2 id="_10-optimization-canon-required" tabindex="-1">10. Optimization Canon (Required) <a class="header-anchor" href="#_10-optimization-canon-required" aria-label="Permalink to &quot;10. Optimization Canon (Required)&quot;">​</a></h2><p>Implementation must follow the speed spec:</p><ol><li>Profile-driven execution (<code>ultrafast|fast|standard|full</code>).</li><li>Changed-file first, full-scan in CI/nightly.</li><li>Parse/config/tool availability cached once per run.</li><li>Parallelize only independent gates with bounded timeout.</li><li>Emit per-gate telemetry (<code>duration_ms</code>, <code>cache_hit</code>, <code>scope</code>, <code>profile</code>).</li></ol><p>Reference: <code>docs/governance/POLYGLOT_GOVERNANCE_SPEED_SPEC_2026-02-20.md</code>.</p>',57)])])}const g=t(o,[["render",r]]);export{u as __pageData,g as default};
